export function translateArTrPhrase(source: string, locale: ArTrLocale): string {
  return AR_TR_TRANSLATIONS[source]?.[locale] || source;
}

export function translateArTrRecord<T extends Record<string, string>>(source: T, locale: ArTrLocale): T {
  return Object.fromEntries(
    Object.entries(source).map(([key, value]) => [key, translateArTrPhrase(value, locale)]),
  ) as T;
}
